<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import SceneDimensionsFields from './SceneDimensionsFields.vue'
import type { Scene } from '../tabletop/types'
const props = defineProps<{
  scenes: Scene[]; activeId: string; master: boolean; busy: boolean; error: string
  remove: (id: string) => Promise<boolean>
  create: (settings: object) => Promise<string | undefined>
  save: (id: string, settings: object) => Promise<boolean>
  activate: (id: string) => Promise<boolean>
  upload: (id: string, image: File) => Promise<boolean>
}>()
const sceneWidth=ref(3200),sceneHeight=ref(2200),newWidth=ref(3200),newHeight=ref(2200),newCell=ref(64)
const createDialog=ref(false),editDialog=ref(false)
const selected = ref(props.activeId), newName = ref(''), name = ref(''), cellSize = ref(64), amount = ref(1.5), unit = ref('m'), grid = ref(true), snap = ref(true)
const dirty = ref(false), localError = ref(''), fileInput = ref<HTMLInputElement>()
const current = computed(() => props.scenes.find(scene => scene.id === selected.value))
const units = [{value:'mm',label:'Milímetros (mm)'},{value:'cm',label:'Centímetros (cm)'},{value:'m',label:'Metros (m)'},{value:'km',label:'Quilômetros (km)'},{value:'in',label:'Polegadas (in)'},{value:'ft',label:'Pés / feet (ft)'},{value:'yd',label:'Jardas (yd)'},{value:'mi',label:'Milhas (mi)'}]
function fill() { const scene = current.value; if (!scene) return; sceneWidth.value=scene.width;sceneHeight.value=scene.height;name.value=scene.name;cellSize.value=scene.cell_size;amount.value=scene.distance_per_cell;unit.value=scene.distance_unit;grid.value=scene.grid_visible;snap.value=scene.snap;dirty.value=false }
function select(id: string) { if (props.busy) return; if (dirty.value && !confirm('Descartar as alterações não salvas deste cenário?')) return; selected.value=id;localError.value='';fill();editDialog.value=props.master }
watch(() => props.scenes, () => { if (!current.value) selected.value=props.activeId; if (!dirty.value) fill() }, {immediate:true})
async function create() { localError.value='';const id=await props.create({name:newName.value,width:newWidth.value,height:newHeight.value,cell_size:newCell.value});if(id){newName.value='';selected.value=id;fill();createDialog.value=false;editDialog.value=true} }
async function save() { if(!current.value)return; const ok=await props.save(current.value.id,{name:name.value,width:sceneWidth.value,height:sceneHeight.value,cell_size:Number(cellSize.value),distance_per_cell:Number(amount.value),distance_unit:unit.value,grid_visible:grid.value,snap:snap.value});if(ok){dirty.value=false;fill();editDialog.value=false} }
async function upload(event: Event) {
  localError.value=''
  const input=event.target as HTMLInputElement, file=input.files?.[0]
  if (!file || !current.value) return
  if(file.size>10*1024*1024){localError.value='A imagem deve ter no máximo 10 MB.';input.value='';return}
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)){localError.value='Selecione uma imagem PNG, JPEG ou WebP.';input.value='';return}
  await props.upload(current.value.id,file);input.value=''
}
async function removeScene(id:string){if(confirm('Excluir este cenário e seus tokens/objetos?'))await props.remove(id)}
</script>
<template>
  <section class="panel-content scenes-menu"><div class="panel-heading"><h2>Cenários</h2><span>{{ scenes.length }} {{ master ? 'NA CAMPANHA' : 'EM EXIBIÇÃO' }}</span></div><p class="panel-help">{{ master ? 'Prepare seus cenários e escolha qual exibir ao grupo.' : 'O mestre escolhe o cenário compartilhado com o grupo.' }}</p>
    <button v-if="master" class="primary full" :disabled="busy" @click="newName = ''; newWidth=3200;newHeight=2200;newCell=64; createDialog = true">+ Novo cenário</button>
    <ul class="scenes-list"><li v-for="scene in scenes" :key="scene.id" class="scene-card"><button :class="{ chosen: activeId === scene.id }" :disabled="busy || !master" @click="select(scene.id)"><img v-if="scene.background_url" :src="scene.background_url" alt="" loading="lazy"><span v-else class="scene-thumb">▦</span><span><strong>{{ scene.name }}</strong><small>{{ scene.distance_per_cell }} {{ scene.distance_unit }} por quadrado</small></span><b v-if="activeId === scene.id">ATIVO</b></button><div v-if="master" class="scene-card-actions"><button :aria-label="`Editar ${scene.name}`" :disabled="busy" @click="select(scene.id)">Editar</button><button v-if="scene.id !== activeId" :disabled="busy" @click="activate(scene.id)">Exibir na mesa</button><button :aria-label="`Excluir ${scene.name}`" :disabled="busy || scenes.length <= 1" :title="scenes.length <= 1 ? 'A mesa deve ter pelo menos um cenário' : 'Excluir cenário'" @click="removeScene(scene.id)">Excluir</button></div></li></ul>
    <q-dialog v-model="createDialog" :persistent="busy"><q-card class="modal scene-modal"><q-card-section><span class="eyebrow">UMA NOVA PAISAGEM</span><h2>Novo cenário</h2><form @submit.prevent="create"><label>Nome do novo cenário<input v-model="newName" required maxlength="100" autofocus placeholder="Ex.: Floresta dos ecos" :disabled="busy"></label><SceneDimensionsFields :width="newWidth" :height="newHeight" :cell="newCell" :disabled="busy" @change="newWidth=$event.width;newHeight=$event.height;newCell=$event.cell" /><p v-if="error" role="alert" class="scene-upload-error">{{ error }}</p><div class="modal-actions"><button type="button" class="text-button" :disabled="busy" @click="createDialog = false">Cancelar</button><button class="primary" :disabled="busy">Criar cenário</button></div></form></q-card-section></q-card></q-dialog>
    <q-dialog v-model="editDialog" :persistent="busy"><q-card v-if="current" class="modal scene-modal"><q-card-section><span class="eyebrow">CONFIGURAÇÃO DO CENÁRIO</span><h2>Editar cenário</h2><form @submit.prevent="save" @input="dirty = true" @change="dirty = true"><label>Nome do cenário<input v-model="name" required maxlength="100" :disabled="busy"></label><SceneDimensionsFields :width="sceneWidth" :height="sceneHeight" :cell="cellSize" :disabled="busy" @change="sceneWidth=$event.width;sceneHeight=$event.height;cellSize=$event.cell;dirty=true" /><label>Distância por quadrado<input v-model="amount" type="number" min="0.000001" max="1000000000" step="any" required :disabled="busy"></label><label for="scene-distance-unit">Unidade de distância</label><select id="scene-distance-unit" v-model="unit" :disabled="busy"><option v-for="item in units" :key="item.value" :value="item.value">{{ item.label }}</option></select><label class="table-checkbox"><input v-model="grid" type="checkbox" :disabled="busy"> Mostrar grid</label><label class="table-checkbox"><input v-model="snap" type="checkbox" :disabled="busy"> Encaixar tokens no grid</label><p v-if="error" role="alert" class="scene-upload-error">{{ error }}</p><div class="modal-actions"><button type="button" class="text-button" :disabled="busy" @click="editDialog = false; dirty = false">Fechar</button><button class="primary" :disabled="busy || !dirty">Salvar cenário</button></div></form>
      <div class="scene-background"><h3>Imagem principal de fundo</h3><img v-if="current.background_url" :src="current.background_url" :alt="`Fundo de ${current.name}`" class="scene-preview"><label>Selecionar imagem<input ref="fileInput" type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="upload"></label><p class="panel-help">Até 10 MB. Para mover ou redimensionar, selecione a camada Fundo e dê dois cliques na imagem.</p><p v-if="localError" role="alert" class="scene-upload-error">{{ localError }}</p></div>
    </q-card-section></q-card></q-dialog>
  </section>
</template>
<style scoped>.scenes-list{list-style:none;margin:0;padding:0}.scenes-list li{margin-bottom:8px}.scenes-list button{width:100%;display:flex;gap:10px;align-items:center;text-align:left;border:1px solid #493254;background:#251b30;color:#d6c1e6;border-radius:8px;padding:10px}.scenes-list button.chosen{border-color:#b98de2;background:#3b2849}.scenes-list img,.scene-thumb{width:45px;height:38px;border-radius:4px;object-fit:cover;flex-shrink:0;background:#4b3659;display:grid;place-items:center}.scene-thumb{font-size:23px;color:#b49ac6}.scenes-list strong{display:block;font-size:11px;overflow-wrap:anywhere;font-weight:500}.scenes-list small{display:block;font-size:9px;color:#ae92c2;margin-top:5px}.scenes-list b{margin-left:auto;font-size:7px;letter-spacing:1px;color:#bfdaa5}.create-scene,.scene-editor{border-top:1px solid #483153;margin-top:24px;padding-top:20px}.scene-editor h3{font-size:13px;line-height:1.6;font-weight:500;margin-bottom:12px}.scene-background{margin-top:25px;padding-top:20px;border-top:1px solid #483153}.scene-preview{max-width:100%;max-height:160px;object-fit:contain;border-radius:7px;background:#130f19}.scene-upload-error{color:#ffc0d0;font-size:11px}.scene-background input[type=file]{font-size:10px;max-width:100%}.scenes-list{margin-top:22px}.scene-card-actions{display:flex;gap:6px;margin:6px 0 18px}.scene-card-actions button{font-size:10px;padding:7px;justify-content:center}.scene-modal select{width:100%;padding:12px;background:#17111e;color:#e3d5ed;border:1px solid #5d426c;border-radius:7px}.scene-modal label{color:#cbb6dd}.scene-modal .scene-upload-error{color:#ffc0d0}.scene-modal{max-height:88vh;overflow:auto}</style>
